using UnityEngine;

namespace RPG.Core
{
    /// <summary>
    /// References to the 3D models the runtime systems build with (trees, rocks, creature models).
    /// Generated by RPG > Setup Art (RpgArtSetup) into Resources/RpgArt.asset so plain code can load it.
    /// Any field may be null; callers fall back to primitive shapes.
    /// </summary>
    public class RpgArt : ScriptableObject
    {
        public GameObject FirTreeA;
        public GameObject FirTreeB;
        public GameObject RoundTree;
        public GameObject TallTree;
        public GameObject RockA;
        public GameObject RockB;
        public GameObject RockC;
        public GameObject Wolf;
        public GameObject Slime;

        // World building
        public Shader VertexLit;
        public Shader Water;
        public GameObject EnemyPrefab;
        public GameObject VillageHouse;
        public GameObject Hut;
        public GameObject HouseBase;
        public GameObject HouseRoof;
        public GameObject HouseDoor;
        public GameObject Fence;
        public GameObject FireFx;
        public GameObject Crate;
        public GameObject Bush;
        public GameObject Flower;
        public GameObject Grass;
        public GameObject TreeLog;
        public GameObject Pumpkin;

        // Player: animator with one attack state per swing type (slash, crush, bash, bow, staff, chop, mine)
        public RuntimeAnimatorController PlayerController;

        // see-through walls between the camera and the player indoors
        public Shader Fade;

        static RpgArt instance;
        static bool loaded;

        public static RpgArt Instance
        {
            get
            {
                if (!loaded)
                {
                    instance = Resources.Load<RpgArt>("RpgArt");
                    loaded = true;
                }
                return instance;
            }
        }
    }
}
